          if (!loaded || browserControlsDisabled) return;
          setBrowserEnabled(next);
          void (async () => {
            const ok = await persist(WORKBENCH_SETTING_KEYS.browserEnabled, String(next), next);
            if (ok && !next) await closeBrowserForDisabledGate();
          })();
        }

